package cn.courselens;
import static org.junit.Assert.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class AiChatsTest {
 @Test public void projectsChatsMemoryAndStrengthSurviveReopen()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiChats store=new AiChats(c);String first=store.project().getString("id"),chat=store.chat().getString("id");store.memory("我更喜欢简洁回答");store.strength(2);store.messages(new JSONArray().put(new JSONObject().put("role","user").put("content","请帮我复习")));store.newProject("英语学习");assertEquals("",store.project().getString("memory"));store.memory("每周复习单词");AiChats reopened=new AiChats(c);assertEquals("英语学习",reopened.project().getString("name"));reopened.select(first,chat);assertEquals(2,reopened.chat().getInt("strength"));assertEquals("我更喜欢简洁回答",reopened.project().getString("memory"));assertEquals("请帮我复习",reopened.chat().getJSONArray("messages").getJSONObject(0).getString("content"));reopened.newChat();assertEquals(0,reopened.chat().getJSONArray("messages").length());assertEquals("我更喜欢简洁回答",reopened.project().getString("memory"));}
 @Test public void temporaryChatsNeverWriteOrReadSavedMemory()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiChats saved=new AiChats(c);saved.memory("持久记忆");String before=c.getSharedPreferences("ai_chats",0).getString("state",null);AiChats temp=new AiChats(c,true);assertEquals("",temp.project().getString("memory"));temp.messages(new JSONArray().put(new JSONObject().put("role","user").put("content","私密草稿")));temp.strength(3);temp.memory("临时记忆");assertEquals(before,c.getSharedPreferences("ai_chats",0).getString("state",null));}
 @Test public void deletingChatsKeepsOtherProjectsMemoryAndAUsableCurrentChat()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiChats store=new AiChats(c);String first=store.project().getString("id"),chat=store.chat().getString("id");store.memory("保留的项目记忆");store.newProject("其他项目");String other=store.project().getString("id"),otherChat=store.chat().getString("id");store.deleteChat(first,chat);assertEquals(otherChat,store.chat().getString("id"));store.select(first,null);assertEquals("保留的项目记忆",store.project().getString("memory"));assertNotEquals(chat,store.chat().getString("id"));store.newChat();String active=store.chat().getString("id");store.deleteChat(first,active);assertNotEquals(active,store.chat().getString("id"));assertEquals(1,store.project().getJSONArray("chats").length());AiChats reopened=new AiChats(c);assertEquals(store.chat().getString("id"),reopened.chat().getString("id"));String before=c.getSharedPreferences("ai_chats",0).getString("state",null);try{store.deleteChat(other,"missing");fail();}catch(IllegalArgumentException expected){}assertEquals(before,c.getSharedPreferences("ai_chats",0).getString("state",null));}
 @Test public void autonomousMemoryCanBeReplacedUndoneAndRejectsStaleEdits()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiChats store=new AiChats(c);store.memory("偏好简洁回答\n旧安排");store.organizeMemory("偏好简洁回答\n旧安排","偏好简洁回答\n新的长期安排");assertEquals("偏好简洁回答\n新的长期安排",new AiChats(c).project().getString("memory"));try{store.organizeMemory("过期快照","覆盖");fail();}catch(IllegalStateException expected){}store.undoMemory();assertEquals("偏好简洁回答\n旧安排",new AiChats(c).project().getString("memory"));assertFalse(store.project().has("memory_previous"));}
 @Test public void oversizedAttachmentsCannotPoisonSavedChatState()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiChats store=new AiChats(c);String before=c.getSharedPreferences("ai_chats",0).getString("state",null);try{store.messages(new JSONArray().put(new JSONObject().put("role","user").put("content","x".repeat(4000001))));fail();}catch(IllegalStateException expected){}assertEquals(0,store.chat().getJSONArray("messages").length());assertEquals(before,c.getSharedPreferences("ai_chats",0).getString("state",null));store.memory("仍可保存记忆");assertEquals("仍可保存记忆",new AiChats(c).project().getString("memory"));}
 @Test public void malformedSavedDataIsNotReplaced()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("ai_chats",0).edit().putString("state","broken").commit();try{new AiChats(c);fail();}catch(Exception expected){}assertEquals("broken",c.getSharedPreferences("ai_chats",0).getString("state",""));}
}
